import org.springframework.web.bind.annotation.RestController;

/** A sheet's pools and their members. The signed-in user's name comes in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/pools")
public class PoolController {

    private static final BigDecimal HUNDRED = new BigDecimal("100.00");

    /** A member, a person or another pool (poolId set, never retired): a retired person (a retirement date set,
     *  whatever the date) counts its share toward the total but is left out of the cuts (0.00, its share spread
     *  over the others; none when every member is retired). Its cut of the pool's pot (two decimals; 0.00 for a person
     *  on hold on the sheet's today, whose share is spread over the others); none when the pool is unbalanced or
     *  has no pot. A member whose dates (from, to: optional) do not include the sheet's today is left out
     *  entirely: it counts 0.00 toward the total and has no cut. */
    public record PoolMemberView(Long personId, Long poolId, String name, String share, boolean retired, String cut,
            LocalDate from, LocalDate to, boolean active) {
    }

    /** A pool, with its total share and whether that is exactly 100.00. A crew is a pool too (crew set): its id is
     *  the crew's id negated, its members its lead and then its members, at equal shares. */
    public record PoolView(long id, String name, List<PoolMemberView> members, String totalShare, boolean balanced,
            boolean crew) {

        /** The sheet's pools as views, in their order. A pool that is a member of another has as its pot its cut
         *  in the pool above (none when that is unbalanced or has none); one that is a member of none has the
         *  sheet's pot. A person on hold on the sheet's today gets no cut from any pool. The crews follow, each a
         *  pool of the sheet's pot. */
        static List<PoolView> of(List<Pool> pools, List<Crew> crews, Map<Long, Person> people, BigDecimal sheetPot,
                LocalDate today) {
            Map<Long, Pool> byId = new HashMap<>();
            Map<Long, Pool> parentOf = new HashMap<>();
            for (Pool pool : pools) {
                byId.put(pool.getId(), pool);
                for (PoolMember m : pool.getMembers()) {
                    if (m.getMemberPoolId() != null) {
                        parentOf.put(m.getMemberPoolId(), pool);
                    }
                }
            }
            Map<Long, PoolView> views = new HashMap<>();
            for (Pool pool : pools) {
                view(pool, byId, parentOf, people, sheetPot, today, views);
            }
            List<PoolView> out = new ArrayList<>(pools.stream().map(p -> views.get(p.getId())).toList());
            for (Crew crew : crews) {
                PoolView v = of(crewPool(crew), byId, people, sheetPot, today);
                out.add(new PoolView(-crew.getId(), v.name(), v.members(), v.totalShare(), v.balanced(), true));
            }
            return out;
        }

        /** A crew as a pool: its lead (when it has one) and then its members, 100.00 split equally between them,
         *  each rounded half to even to two decimals, the remainder on the first; none when it has no one. */
        private static Pool crewPool(Crew crew) {
            Pool pool = new Pool(crew.getSheetId(), crew.getName());
            List<Long> ids = new ArrayList<>();
            if (crew.getLeadId() != null) {
                ids.add(crew.getLeadId());
            }
            crew.getMembers().forEach(m -> ids.add(m.getPersonId()));
            if (ids.isEmpty()) {
                return pool;
            }
            BigDecimal each = HUNDRED.divide(BigDecimal.valueOf(ids.size()), 2, RoundingMode.HALF_EVEN);
            BigDecimal lead = HUNDRED.subtract(each.multiply(BigDecimal.valueOf(ids.size() - 1)));
            for (int i = 0; i < ids.size(); i++) {
                pool.addMember(ids.get(i), i == 0 ? lead : each, null, null);
            }
            return pool;
        }

        private static PoolView view(Pool pool, Map<Long, Pool> byId, Map<Long, Pool> parentOf,
                Map<Long, Person> people, BigDecimal sheetPot, LocalDate today, Map<Long, PoolView> views) {
            PoolView done = views.get(pool.getId());
            if (done != null) {
                return done;
            }
            BigDecimal pot = sheetPot;
            Pool parent = parentOf.get(pool.getId());
            if (parent != null) {
                PoolView above = view(parent, byId, parentOf, people, sheetPot, today, views);
                String cut = above.members().stream().filter(m -> pool.getId().equals(m.poolId())).findFirst()
                        .map(PoolMemberView::cut).orElse(null);
                pot = cut == null ? null : new BigDecimal(cut);
            }
            PoolView v = of(pool, byId, people, pot, today);
            views.put(pool.getId(), v);
            return v;
        }

        private static PoolView of(Pool pool, Map<Long, Pool> pools, Map<Long, Person> people, BigDecimal pot,
                LocalDate today) {
            List<PoolMember> all = pool.getMembers();
            BigDecimal total = BigDecimal.ZERO.setScale(2);
            boolean[] retired = new boolean[all.size()];
            boolean[] held = new boolean[all.size()];
            boolean[] active = new boolean[all.size()];
            boolean allRetired = true;
            for (int i = 0; i < all.size(); i++) {
                Long personId = all.get(i).getPersonId();
                Person p = personId == null ? null : people.get(personId);
                retired[i] = p != null && p.isRetired();
                held[i] = p != null && today != null && p.heldOn(today);
                active[i] = today == null || all.get(i).activeOn(today);
                if (active[i]) {
                    total = total.add(all.get(i).getShare());
                    allRetired &= retired[i];
                }
            }
            boolean balanced = total.compareTo(HUNDRED) == 0;
            BigDecimal[] cuts = balanced && pot != null && !allRetired ? cuts(all, retired, held, active, pot) : new BigDecimal[all.size()];
            List<PoolMemberView> members = new ArrayList<>();
            for (int i = 0; i < all.size(); i++) {
                PoolMember m = all.get(i);
                String name;
                if (m.getMemberPoolId() != null) {
                    Pool member = pools.get(m.getMemberPoolId());
                    name = member == null ? "" : member.getName();
                } else {
                    Person p = people.get(m.getPersonId());
                    name = p == null ? "" : p.getName();
                }
                members.add(new PoolMemberView(m.getPersonId(), m.getMemberPoolId(), name,
                        m.getShare().setScale(2).toPlainString(), retired[i],
                        cuts[i] == null ? null : cuts[i].toPlainString(), m.getFromDate(), m.getToDate(),
                        active[i]));
            }
            return new PoolView(pool.getId() == null ? 0 : pool.getId(), pool.getName(), members,
                    total.setScale(2).toPlainString(), balanced, false);
        }

        /** Each member's cut of the pot: the pot times their share divided by the shares of the members with a
         *  cut added up, rounded half to even to two decimals (0.00 for a retired one or one on hold, whose share is
         *  spread over the others in proportion to theirs); the
         *  remainder, the pot minus the cuts added up, goes to the member with the smallest non-zero cut, the
         *  latest added on a tie (when no cut is non-zero, to the last member with a cut and a share), so the cuts
         *  total exactly the pot. When no member has a cut, each is 0.00.
         *  A member not active on the sheet's today has none at all. */
        private static BigDecimal[] cuts(List<PoolMember> members, boolean[] retired, boolean[] held,
                boolean[] active, BigDecimal pot) {
            BigDecimal[] cuts = new BigDecimal[members.size()];
            BigDecimal shares = BigDecimal.ZERO;
            for (int i = 0; i < members.size(); i++) {
                if (active[i] && !retired[i] && !held[i]) {
                    shares = shares.add(members.get(i).getShare());
                }
            }
            BigDecimal sum = BigDecimal.ZERO.setScale(2);
            int smallest = -1;
        int last = -1;
            for (int i = 0; i < members.size(); i++) {
                if (!active[i]) {
                    continue;
                }
                BigDecimal share = members.get(i).getShare();
                boolean cut = !retired[i] && !held[i] && shares.signum() > 0;
                cuts[i] = cut ? pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN)
                        : BigDecimal.ZERO.setScale(2);
                sum = sum.add(cuts[i]);
                if (cut && share.signum() > 0) {
                    last = i;
                }
                if (cut && cuts[i].signum() != 0
                        && (smallest < 0 || cuts[i].compareTo(cuts[smallest]) <= 0)) {
                    smallest = i;
                }
            }
            int to = smallest >= 0 ? smallest : last;
            if (to >= 0) {
                cuts[to] = cuts[to].add(pot.setScale(2).subtract(sum));
            }
            return cuts;
        }
    }

    public record PoolRequest(@Size(max = 200) String name) {
    }

    public record PoolMemberRequest(Long personId, Long poolId, BigDecimal share, LocalDate from, LocalDate to) {
    }

    private final PoolService service;
    private final CrewService crews;
    private final PersonRepository people;
    private final SheetService sheets;
    private final AsOf asOf;

    public PoolController(PoolService service, CrewService crews, PersonRepository people, SheetService sheets,
            AsOf asOf) {
        this.service = service;
        this.crews = crews;
        this.people = people;
        this.sheets = sheets;
        this.asOf = asOf;
    }

    /** The sheet's pools, in the order they were added; reckoned on the date, with its people and its pot as they
     *  stood then, when the screen views the sheet as of one. */
    @GetMapping
    @Transactional(readOnly = true)
    public List<PoolView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestHeader(value = AsOf.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        String sid = sheetId.trim();
        if (asOf == null) {
            return views(sid);
        }
        Map<Long, Person> then = this.asOf.people(sid, asOf).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        return PoolView.of(service.list(sid), crews.list(sid), then, this.asOf.sheet(sid, asOf).getPot(), asOf);
    }

    /** Add a pool to the sheet. */
    @PostMapping
    public PoolView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid PoolRequest request) {
        String sid = sheetId.trim();
        return view(sid, service.add(sid, user.trim(), request.name()));
    }

    /** Add a member to a pool with a share: a person, or another pool. */
    @PostMapping("/{poolId}/members")
    public PoolView addMember(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable long poolId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid PoolMemberRequest request) {
        String sid = sheetId.trim();
        Pool pool = service.addMember(sid, user.trim(), poolId, request.personId(), request.poolId(),
                request.share(), request.from(), request.to());
        return view(sid, pool);
    }

    private List<PoolView> views(String sheetId) {
        return PoolView.of(service.list(sheetId), crews.list(sheetId), people(sheetId), sheets.pot(sheetId), sheets.today(sheetId));
    }

    private PoolView view(String sheetId, Pool pool) {
        return views(sheetId).stream().filter(v -> !v.crew() && v.id() == pool.getId()).findFirst().orElseThrow();
    }

    private Map<Long, Person> people(String sheetId) {
        return people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
    }

    /** A pool or member that cannot be added is refused with the reason, for the screen to show. */
    @ExceptionHandler(PoolRefusedException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> refused(PoolRefusedException e) {
        return Map.of("message", e.getMessage());
    }
}
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.crew.CrewRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps each sheet's pools and their members. */
@Service
public class PoolService {

    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
    private static final int MAX_DEPTH = 3;

    private final PoolRepository pools;
    private final CrewRepository crews;
    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;

    public PoolService(PoolRepository pools, CrewRepository crews, PersonRepository people, SheetService sheets,
            Audit audit) {
        this.pools = pools;
        this.crews = crews;
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's pools, in the order they were added. */
    @Transactional(readOnly = true)
    public List<Pool> list(String sheetId) {
        return pools.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add a pool by a name (surrounding spaces removed); a blank name, or one already taken by a pool or a crew,
     *  is refused. */
    @Transactional
    public Pool add(String sheetId, String user, String name) {
        sheets.today(sheetId);
        String n = name == null ? "" : name.trim();
        if (n.isEmpty()) {
            throw new PoolRefusedException("Enter a pool name.");
        }
        if (pools.existsBySheetIdAndName(sheetId, n)) {
            throw new PoolRefusedException("\"" + n + "\" is already a pool.");
        }
        if (crews.existsBySheetIdAndName(sheetId, n)) {
            throw new PoolRefusedException("\"" + n + "\" is already a crew, and a crew is a pool.");
        }
        Pool saved = pools.saveAndFlush(new Pool(sheetId, n));
        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + n);
        return saved;
    }

    /** Add a member to a pool with a share percent: a person of the sheet, or another of its pools (poolId).
     *  Refused: a share not more than 0.00 and at most 100.00 in two decimals; a person already in it; a pool
     *  that would contain itself through any chain, that is already a member of a pool, or that would make a
     *  chain of pools more than three deep; a to-date before the from-date (both optional). */
    @Transactional
    public Pool addMember(String sheetId, String user, long poolId, Long personId, Long memberPoolId,
            BigDecimal share, LocalDate from, LocalDate to) {
        Pool pool = pools.findByIdAndSheetId(poolId, sheetId)
                .orElseThrow(() -> new PoolRefusedException("No such pool."));
        Person person = personId == null ? null : people.findByIdAndSheetId(personId, sheetId).orElse(null);
        Pool member = memberPoolId == null ? null : pools.findByIdAndSheetId(memberPoolId, sheetId).orElse(null);
        if ((person == null) == (member == null)) {
            throw new PoolRefusedException("Choose a person or a pool.");
        }
        if (share == null || share.stripTrailingZeros().scale() > 2 || share.signum() <= 0
                || share.compareTo(HUNDRED) > 0) {
            throw new PoolRefusedException("Enter a share more than 0.00 and at most 100.00, in two decimals.");
        }
        if (from != null && to != null && to.isBefore(from)) {
            throw new PoolRefusedException("A membership cannot end before it starts.");
        }
        BigDecimal s = share.setScale(2);
        String name;
        if (person != null) {
            if (pool.hasMember(person.getId())) {
                throw new PoolRefusedException(person.getName() + " is already in " + pool.getName() + ".");
            }
            pool.addMember(person.getId(), s, from, to);
            name = person.getName();
        } else {
            refuseMemberPool(sheetId, pool, member);
            pool.addMemberPool(member.getId(), s, from, to);
            name = member.getName();
        }
        Pool saved = pools.saveAndFlush(pool);
        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
                + " name=" + name + " share=" + s.toPlainString() + (from == null ? "" : " from=" + from)
                + (to == null ? "" : " to=" + to));
        return saved;
    }

    /** Refuse making a pool a member of another when it would contain itself, is already a member of a pool,
     *  or the chain of pools would be more than three deep. */
    private void refuseMemberPool(String sheetId, Pool pool, Pool member) {
        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
        Map<Long, Long> parentOf = new HashMap<>();
        for (Pool p : all) {
            for (PoolMember m : p.getMembers()) {
                if (m.getMemberPoolId() != null) {
                    parentOf.put(m.getMemberPoolId(), p.getId());
                }
            }
        }
        int levelsAbove = 0;
        for (Long at = pool.getId(); at != null; at = parentOf.get(at)) {
            if (at.equals(member.getId())) {
                throw new PoolRefusedException(member.getName() + " cannot contain itself.");
            }
            levelsAbove++;
        }
        Long above = parentOf.get(member.getId());
        if (above != null) {
            String in = all.stream().filter(p -> p.getId().equals(above)).map(Pool::getName).findFirst().orElse("");
            throw new PoolRefusedException(member.getName() + " is already in " + in + ".");
        }
        if (levelsAbove + depth(member, all) > MAX_DEPTH) {
            throw new PoolRefusedException("A chain of pools is at most " + MAX_DEPTH + " deep.");
        }
    }

    /** How many levels of pools a pool heads: 1, and the deepest of the pools in it. */
    private static int depth(Pool pool, List<Pool> all) {
        int below = 0;
        for (PoolMember m : pool.getMembers()) {
            if (m.getMemberPoolId() != null) {
                Pool child = all.stream().filter(p -> p.getId().equals(m.getMemberPoolId())).findFirst().orElse(null);
                if (child != null) {
                    below = Math.max(below, depth(child, all));
                }
            }
        }
        return 1 + below;
    }
}
package net.officefloor.hq.app.pool;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A member of a pool, with its share percent of it: a person, or another pool of the sheet. */
@Entity
@Table(name = "pool_member")
public class PoolMember {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "person_id")
    private Long personId;

    @Column(name = "member_pool_id")
    private Long memberPoolId;

    @Column(name = "share", nullable = false, precision = 5, scale = 2)
    private BigDecimal share;

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    protected PoolMember() {
    }

    PoolMember(Long personId, Long memberPoolId, BigDecimal share, LocalDate fromDate, LocalDate toDate) {
        this.personId = personId;
        this.memberPoolId = memberPoolId;
        this.share = share;
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public Long getId() {
        return id;
    }

    /** The person, or none when the member is a pool. */
    public Long getPersonId() {
        return personId;
    }

    /** The pool, or none when the member is a person. */
    public Long getMemberPoolId() {
        return memberPoolId;
    }

    public BigDecimal getShare() {
        return share;
    }

    /** The first day of the membership; none means from always. */
    public LocalDate getFromDate() {
        return fromDate;
    }

    /** The last day of the membership; none means for good. */
    public LocalDate getToDate() {
        return toDate;
    }

    /** Whether the membership's dates include a date. */
    public boolean activeOn(LocalDate date) {
        return (fromDate == null || !date.isBefore(fromDate)) && (toDate == null || !date.isAfter(toDate));
    }

    void setPersonId(Long personId) {
        this.personId = personId;
    }

    void setShare(BigDecimal share) {
        this.share = share;
    }
}
package net.officefloor.hq.app.pool;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;

/** A sheet's pool: a name, and its members, each a person or another pool with a share percent. */
@Entity
@Table(name = "pool")
public class Pool {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "pool_id", nullable = false)
    private List<PoolMember> members = new ArrayList<>();

    protected Pool() {
    }

    public Pool(String sheetId, String name) {
        this.sheetId = sheetId;
        this.name = name;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    /** Its members, in the order they were added. */
    public List<PoolMember> getMembers() {
        return members.stream()
                .sorted(Comparator.comparing(PoolMember::getId, Comparator.nullsLast(Comparator.naturalOrder())))
                .toList();
    }

    public boolean hasMember(long personId) {
        return members.stream().anyMatch(m -> Objects.equals(m.getPersonId(), personId));
    }

    public boolean hasMemberPool(long poolId) {
        return members.stream().anyMatch(m -> Objects.equals(m.getMemberPoolId(), poolId));
    }

    /** Add a person with a share, from and to a date when given. */
    public void addMember(long personId, BigDecimal share, LocalDate from, LocalDate to) {
        members.add(new PoolMember(personId, null, share, from, to));
    }

    /** Add another pool with a share, from and to a date when given. */
    public void addMemberPool(long poolId, BigDecimal share, LocalDate from, LocalDate to) {
        members.add(new PoolMember(null, poolId, share, from, to));
    }

    /** Drop a person's membership. */
    public void removeMember(long personId) {
        members.removeIf(m -> Objects.equals(m.getPersonId(), personId));
    }

    /** Move a person's membership to another: their share is added to the other's (at most 100.00) when the
     *  other is already a member. */
    public void moveMember(long fromId, long intoId) {
        PoolMember moving = members.stream().filter(m -> Objects.equals(m.getPersonId(), fromId)).findFirst().orElse(null);
        if (moving == null) {
            return;
        }
        PoolMember kept = members.stream().filter(m -> Objects.equals(m.getPersonId(), intoId)).findFirst().orElse(null);
        if (kept == null) {
            moving.setPersonId(intoId);
            return;
        }
        members.remove(moving);
        kept.setShare(kept.getShare().add(moving.getShare()).min(new BigDecimal("100.00")));
    }
}

