  await expect(pg_uma.getByTestId("header-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("header-overdue-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("my-due-total")).toHaveText("");
  await expect(pg_uma.getByTestId("summary-period-2026-03-change")).toHaveText("0.50");
  await expect(pg_uma.getByTestId("summary-period-2026-04-change")).toHaveText("1.05");
  await expect(pg_uma.getByTestId("summary-status-DRAFT-count")).toHaveText("2");
  await expect(pg_uma.getByTestId("summary-status-OPEN-count")).toHaveText("2");
  await expect(pg_uma.getByTestId("summary-status-PENDING-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("summary-status-SETTLED-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("summary-status-VOID-count")).toHaveText("1");
