  await expect(pg_uma.getByTestId("classic-period-2026-04-due-total")).toHaveText("1.55");
  await expect(pg_uma.getByTestId("classic-due-total")).toHaveText("2.05");
  await expect(pg_uma.getByTestId("month-2026-03-due-total")).toHaveText("2.05");
  await expect(pg_uma.getByTestId("pool-row-C1").getByTestId("pool-total-share")).toHaveText("100.00");
  await expect(pg_uma.getByTestId("pool-row-C1").getByTestId("pool-balanced")).toHaveText("yes");
  await expect(pg_uma.getByTestId("pool-member-C1-" + p_cam).getByTestId("pool-share")).toHaveText("33.34");
  await expect(pg_uma.getByTestId("pool-member-C1-" + p_cam).getByTestId("pool-cut")).toHaveText("");
  await expect(pg_uma.getByTestId("pool-member-C1-" + p_cam).getByTestId("pool-cut-2026-02")).toHaveText("");
  await expect(pg_uma.getByTestId("pool-member-C1-" + p_ben).getByTestId("pool-share")).toHaveText("33.33");
  await expect(pg_uma.getByTestId("pool-member-C1-" + p_ben).getByTestId("pool-cut")).toHaveText("");
  await expect(pg_uma.getByTestId("pool-member-C1-" + p_ben).getByTestId("pool-cut-2026-02")).toHaveText("");
  await expect(pg_uma.getByTestId("pool-member-C1-" + p_ada).getByTestId("pool-share")).toHaveText("33.33");
  await expect(pg_uma.getByTestId("pool-member-C1-" + p_ada).getByTestId("pool-cut")).toHaveText("");
  await expect(pg_uma.getByTestId("pool-member-C1-" + p_ada).getByTestId("pool-cut-2026-02")).toHaveText("");
  await expect(pg_uma.getByTestId("crew-row-C1").getByTestId("crew-lead")).toHaveText("Cam");
